UPDATE z000_sd_pay_flow_bill
SET endorser = #{item.endorser}, endorser_acc = #{item.endorserAcc}, amt = #{item.amt},
    sign_date = #{item.signDate}, bill_type = #{item.billType}, bill_scope = #{item.billScope},
    acceptor = #{item.acceptor}, drawer = #{item.drawer}, payee = #{item.payee},
    issue_date = #{item.issueDate}, due_date = #{item.dueDate},
    summary = #{item.summary}, cust = #{item.cust}
WHERE bill_no = #{item.billNo} AND sub_bill_from = #{item.subBillFrom}
  AND sub_bill_to = #{item.subBillTo} AND cmpy = #{item.cmpy}
  AND holder_acc = #{item.holderAcc}

